import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/column/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E4%B8%8E%E5%AE%9E%E6%88%9823%E8%AE%B2/18.html","title":"17-数据获取与分析：常见的 SQL 技巧和分析方法","lang":"zh-CN","frontmatter":{"title":"17-数据获取与分析：常见的 SQL 技巧和分析方法","icon":"blog","date":"2025-09-20T18:24:03.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"description":"你好，我是悦创。 今天我主要讲解如何用 SQL 提数和分析。 本课时分为三部分： 数据获取前期准备； SQL 提数常见问题； 常用的分析方法； 1. 数据获取前期准备 一般来说，在正式写 SQL 之前，要花 1 天时间去做以下几件事： 了解清楚业务方和研发说的是哪张表、哪份日志； 了解这些表和日志的筛选条件是什么，为什么要这么筛选； 了解这些表和日志之...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"17-数据获取与分析：常见的 SQL 技巧和分析方法\\",\\"image\\":[\\"https://bornforthis.cn/gzh.jpg\\",\\"https://bornforthis.cn/zsxq.jpg\\"],\\"datePublished\\":\\"2025-09-20T18:24:03.000Z\\",\\"dateModified\\":\\"2025-09-20T13:37:33.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"AI悦创\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/column/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E4%B8%8E%E5%AE%9E%E6%88%9823%E8%AE%B2/18.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"17-数据获取与分析：常见的 SQL 技巧和分析方法"}],["meta",{"property":"og:description","content":"你好，我是悦创。 今天我主要讲解如何用 SQL 提数和分析。 本课时分为三部分： 数据获取前期准备； SQL 提数常见问题； 常用的分析方法； 1. 数据获取前期准备 一般来说，在正式写 SQL 之前，要花 1 天时间去做以下几件事： 了解清楚业务方和研发说的是哪张表、哪份日志； 了解这些表和日志的筛选条件是什么，为什么要这么筛选； 了解这些表和日志之..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://bornforthis.cn/gzh.jpg"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-09-20T13:37:33.000Z"}],["meta",{"property":"article:author","content":"AI悦创"}],["meta",{"property":"article:published_time","content":"2025-09-20T18:24:03.000Z"}],["meta",{"property":"article:modified_time","content":"2025-09-20T13:37:33.000Z"}]]},"git":{"createdTime":1669634625000,"updatedTime":1758375453000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":14,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":1}],"changelog":[{"hash":"f11d8bedf1266bb848e08120124ad6c056dca5ea","time":1758375453000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs(数据分析思维与实战23讲): 添加第18讲内容及配套图片资源"},{"hash":"42ad15d1fa64e79d3bbbd7b525a0d67003921939","time":1758364818000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs(Vpn-clash-win-mac): 添加ChatGPT相关问题及图片资源"},{"hash":"7548108b868e5f8dc986369422db8825596a5f4f","time":1748782067000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add FAQ articles for programming course: addressing students with prior experience and learning plans by age group"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"b2b6115182448c786784f88a3e325eec83b9c4fe","time":1747017995000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"<a href=\\"http://xn--FAQ04-y40k96e.md\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">更新FAQ04.md</a>，新增0～3岁和3～6岁的学习计划阶段"},{"hash":"2461710ae7016517f2fbd6cc4e6441ed8516e464","time":1747016674000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"新增FAQ04.md文档，提供每个年龄段的学习计划及辅导班信息"},{"hash":"70353fead4a0a1bfadb60ece94c0f3a9f80bfc08","time":1746926862000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新文件夹名称"},{"hash":"ae8a442bae9aa264fee20e42267291df3a74b667","time":1746879162000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新食谱文档，优化标签和步骤格式"},{"hash":"9bfdcd8407ca12cf09f385c602eb1c60cc5f3c56","time":1745906987000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"新增 Vuepress 侧边栏自定义文档，包含自动生成侧边栏的说明及相关信息"},{"hash":"4d098f34b968c7f9162e7d143141d46669c76d6e","time":1745325668000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add articles on programming and cooking: \\"Can computer programs really kill people?\\" and \\"清蒸鲈鱼\\""},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":9.49,"words":2848},"filePathRelative":"column/数据分析思维与实战23讲/18.md","excerpt":"<p>你好，我是悦创。</p>\\n<p>今天我主要讲解如何用 SQL 提数和分析。</p>\\n<p>本课时分为三部分：</p>\\n<ul>\\n<li>\\n<p>数据获取前期准备；</p>\\n</li>\\n<li>\\n<p>SQL 提数常见问题；</p>\\n</li>\\n<li>\\n<p>常用的分析方法；</p>\\n</li>\\n</ul>\\n<h2>1. 数据获取前期准备</h2>\\n<p>一般来说，在正式写 SQL 之前，要花 1 天时间去做以下几件事：</p>\\n<ul>\\n<li>\\n<p>了解清楚业务方和研发说的是哪张表、哪份日志；</p>\\n</li>\\n<li>\\n<p>了解这些表和日志的筛选条件是什么，为什么要这么筛选；</p>\\n</li>\\n<li>\\n<p>了解这些表和日志之前有什么坑，是不是哪天数据有缺失；</p>\\n</li>\\n<li>\\n<p>验证现在是否有坑，<code>select *</code> ，先跑一个核心数据看下。</p>\\n</li>\\n</ul>","autoDesc":true}`),a={name:`18.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>你好，我是悦创。</p><p>今天我主要讲解如何用 SQL 提数和分析。</p><p>本课时分为三部分：</p><ul><li><p>数据获取前期准备；</p></li><li><p>SQL 提数常见问题；</p></li><li><p>常用的分析方法；</p></li></ul><h2 id="_1-数据获取前期准备" tabindex="-1"><a class="header-anchor" href="#_1-数据获取前期准备"><span>1. 数据获取前期准备</span></a></h2><p>一般来说，在正式写 SQL 之前，要花 1 天时间去做以下几件事：</p><ul><li><p>了解清楚业务方和研发说的是哪张表、哪份日志；</p></li><li><p>了解这些表和日志的筛选条件是什么，为什么要这么筛选；</p></li><li><p>了解这些表和日志之前有什么坑，是不是哪天数据有缺失；</p></li><li><p>验证现在是否有坑，<code>select *</code> ，先跑一个核心数据看下。</p></li></ul><p>一旦你做了这几件事之后，你对表和数据就会有一定的感觉。在此基础上，再把问题的拆解模块构思一次，哪些点不好做，心理上要有个预期。前期准备非常重要，很多同学在提数这块花了大量时间，原因就是前期工作做得不到位，太相信我们的埋点。</p><h2 id="_2-sql-提数常见问题" tabindex="-1"><a class="header-anchor" href="#_2-sql-提数常见问题"><span>2. SQL 提数常见问题</span></a></h2><p>提数的最终目的就是为了分析，SQL 提数看似很简单，但往往会因为其他事项而比较花时间。比如：</p><ul><li>被各种各样的其他事情打扰；</li><li>遇到一些坑需要思考；</li><li>突然找到一个新的点，就一直往下深挖；</li><li>自己本身不会提数和分析，不知道如何看数据。</li></ul><p>这些都比较耽误时间，我们逐一来看。</p><p>如果经常被各种各样的事情打扰，你首先一定要有集中时间管理的意识，其次你要认识到当前最重要的事情就是 SQL 提数和分析，也就是说你目前所有的事情当中，优先级最高的就是这件事。 时间管理上具体可以给你以下建议：</p><ul><li><p>早上时间一定要利用好，早点到公司，因为下午大部分都有会，会议的时间也不太好控制，所以早上时间一定要利用好；</p></li><li><p>提前了解好会议主题，不要别人拉你去参加一个会，你傻乎乎就直接去了，到了之后发现这个会议好像跟你没啥关系，然后走也不太好走，所以一定要先确定是否必须参加；</p></li><li><p>中间所有进来的插队需求，先靠边站；</p></li><li><p>利用晚上回家时间、周末时间在这件事上多下功夫，专注去做事，一旦你专注之后，其实别人也不太好意思打扰你。</p></li></ul><p>在“坑”这件事上， 踩坑是必然的，不过我们可以通过这件事来观人阅事 。比如，某个团队中，谁比较靠谱，谁比较好说话，谁尽量不要接触。遇到坑之后，一定要用文档详细记下来，这样做有两个好处：一是可以让团队中的其他人知道，节省团队时间；二是每月总结的时候，知道自己在哪块花了大量时间，可以为后续做分析节省时间。</p><p>如果突然找到一个新的点，或者说突然很纠结某个点 。比如在分析不同年龄段的用户上网时段分布后，突然发现未满 18 周岁的群体分布很奇怪，觉得终于找到一个亮点，然后就持续往下研究这部分人为何这样？最后花了大量时间在这块的分析上，最后往往也没什么结论。所以一定要跳出小的圈子，我们最重要的事情是先把问题的拆解模块做完 。</p><p>如果你不会 SQL 提数，就要学如何提数。我在前面或多或少也说了一些方法，比如看同事是怎么写 SQL 的。如果你真的不会，可以参考同事。前期你可以多接需求多帮别人提数，这样可以熟能生巧。这里我再贴下 SQL 常见问题，如下图所示。</p><figure><img src="/assets/CgqCHl8ehjaAJVcSAACk5p0P1V0330-DJjIj8N4.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="_3-常用的分析方法" tabindex="-1"><a class="header-anchor" href="#_3-常用的分析方法"><span>3. 常用的分析方法</span></a></h2><p>提数完成之后，如何分析呢？实际上就是以下这几种常见的分析方法，我们逐一来看。</p><h3 id="_3-1-结构分析" tabindex="-1"><a class="header-anchor" href="#_3-1-结构分析"><span>3.1 结构分析</span></a></h3><p>第一个就是结构分析，比如，渠道新增用户数，五个渠道 A、B、C、D、E，相对应的新增用户分别是 1w、2w、3w、4w、5w，然后合计一共是 15w，如图所示。</p><figure><img src="/assets/CgqCHl8ehkaAaI8VAAEZ9iIGwXc606-ByeLaQ47.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>那结构分析就是说我们渠道的构成是什么样子。 D 和 E 渠道的新增用户数总和占全渠道新增用户数的 60%，这就是结构分析。这是最基础的数据结构分析，而且管理层一定会问目前渠道分布是什么样子，所以拿到数据之后都要做结构分析。</p><h3 id="_3-2-对比分析" tabindex="-1"><a class="header-anchor" href="#_3-2-对比分析"><span>3.2 对比分析</span></a></h3><p>对比分析我们前面也提到过，我们再加强一次，这个时候你听起来可能会更有感觉。</p><p>所有的数据只有对比才有意义，每年的双 11 都会与之前的双 11 进行消费额对比。实际工作中，最常见的对比对象就是大盘，比如新上线一个功能，怎么样评估这个功能效果，除了看功能使用人数，更加要做的是这个功能的留存和大盘的留存对比 。</p><p>举个例子：我们需要看自身 App 跟竞品的重合用户，与自身 App 的所有用户在客户端内的消费差异，从而针对这些重合用户，做针对性运营，这个时候就要用到对比分析。因为我们的目的是想看竞品用户到底喜欢什么。</p><p>以微视这款 App 为例，你会看到第一列微视与抖音的重合用户消费分类和第三列微视大盘消费分类的消费 CTR 数据（如下图所示）。</p><figure><img src="/assets/Ciqc1F8ehlSASlrzAAB0fPpGWBM118-ry_lA6CE.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>利用对比分析可以算出微视与抖音的重合用户更加偏爱哪些分类（如下图所示）。</p><figure><img src="/assets/CgqCHl8ehl-AZIlLAACcvaG4hys460-B9pX96Qy.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>这里的相对值 diff ，它的计算方式是第二列的消费 CTR 除以第四列的消费 CTR 再减 1 ，然后你会发现搞笑、舞蹈、明星、美食分类，它的相对值是很明显的正向。因此，我们会针对这部分重合用户多推这些内容，减少其他内容权重，这就是对比分析最直接的效果。</p><h3 id="_3-3-时间序列分析" tabindex="-1"><a class="header-anchor" href="#_3-3-时间序列分析"><span>3.3 时间序列分析</span></a></h3><p>第三个分析方法就是时间序列分析， 一般看某指标时，都会把时序周期拉长，看数据趋势，而数据都是波动的，所以都会进行拆解分析，寻找具体波动项 。</p><p>举个例子：新增用户的次日留存近半年出现下降，需要进行渠道维度拆解分析，看整体下降是因为所有的渠道下降还是某个别的渠道下降导致的。</p><p>这是一个模拟数据（如下图所示）：</p><figure><img src="/assets/Ciqc1F8ehmaAZWF6AABYesH2eVY376-DMA6kJLP.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>这是原始数据（如下图所示）：</p><figure><img src="/assets/Ciqc1F8ehm2ARhdAAABfiKswGO4134-CZdg73Bd.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>根据原始数据利用透视图功能插入透视图（如下图所示）：</p><figure><img src="/assets/CgqCHl8ehn-APTTAAADFIELwQjk288-s7__PX42.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>然后就得到这样一个横列的二维数据（如下图所示）：</p><figure><img src="/assets/Ciqc1F8ehoyAZyo9AAEHqyfZ1s8288-BvZIAX-2.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>基于这个二维数据，我们再利用插入图表功能得到（如下图所示）：</p><figure><img src="/assets/Ciqc1F8ehpqAM8HCAAD8MLh6S88072-SOhUxv65.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>从图表发现 A 渠道变化不大，C 渠道是上升，只有 B 渠道是下降。因此是 B 渠道出现问题，需要对 B 渠道进行优化，这就是时间序列分析的效果。</p><h3 id="_3-4-相关性分析" tabindex="-1"><a class="header-anchor" href="#_3-4-相关性分析"><span>3.4 相关性分析</span></a></h3><p>第四个分析方法就是相关性分析，我们前面也说过，比如在第 09 课时，传统行业数据分析那节课里面，产品单价和销售额之间有没有一种明显的正相关性？我们是要进行相关性分析的。</p><p>之前你在每节课里面看到的思维导图有很多模块，最后都是变量，那么这些变量之间有没有相关性呢？这也可以去做分析。这个例子我就不说了，你可以去把相关性知识补习下。因为当你分析有很多变量，很多因子的时候，就要去分析因子之间相关性怎么样？</p><h3 id="_3-5-机器学习" tabindex="-1"><a class="header-anchor" href="#_3-5-机器学习"><span>3.5 机器学习</span></a></h3><p>第五个分析方法就是机器学习，之前我们也讲过这个例子，如下图所示。</p><figure><img src="/assets/CgqCHl8ehsSAXK6TAARNB9wtKnE357-20250920213628271-BAMJdS5y.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>我们发现有很多变量，有很多因子。最后从结果发现开通月数和电子支付这两个变量是目前最能够影响用户，那就针对这两个变量去搞事情。</p><h2 id="_4-总结" tabindex="-1"><a class="header-anchor" href="#_4-总结"><span>4. 总结</span></a></h2><p>最后我总结一下，实际上所有的分析都是基于用户的基础属性和行为属性。如果你还是不会，那就从 5W1H 出发，每次分析时都以这个为模板展开即可。</p><ul><li>Who：指用户基础属性、用户画像。</li><li>Where：渠道分析，渠道入口，用户从哪里来。</li><li>When：时间上的特征。</li><li>What：用户使用了什么功能，哪些行为更加重要。</li><li>Why：为什么要这么做，用户是主动还是被动做的。</li><li>How：怎么做的，行为路径是什么。</li></ul><p>每次遇到问题时，如果你前面的点都没记住，那你可以从这 5W1H 去想。</p><p>提数和分析完成之后，先不要急着写报告，要先把一些关键数据和初步结论同步给业务方核心人员，约个时间一起看下。这样做有两个目的，一是看他们怎么理解这个数据，有无明显问题。二是他们基于这些数据结论，准备怎么落地，需要他们提前想方案。在这个基础上，再去撰写报告 。</p><p>今天的课程就到这里，你做 SQL 提数时经常遇到哪些问题？可以在下方留言与我交流。同时欢迎你关注我本人的公众号（微信搜索：AI悦创），之后会定期更新原创高质量的数据分析文章，下节课见，谢谢。</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Web、Linux」，招收学员面向国内外，国外占 80%。全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,63)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};